{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Isocorydine, an aporphine alkaloid with a similar N-methyltetrahydroisoquinoline and methoxy-substituted aromatic framework, was detected in rat brain within 10 minutes of administration, demonstrating effective BBB crossing for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "S(+)-apomorphine, a close aporphine analogue sharing the N-methyltetrahydroisoquinoline core, showed a brain-to-plasma AUC ratio of 228% in mice, confirming CNS penetration of this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tylocrebrine, a lipophilic polycyclic methoxy-substituted alkaloid, rapidly accumulated in mouse brain with an AUCbrain of 2.1 µg·h/mL, supporting brain access for alkaloids similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Demethyleneberberine, a related isoquinoline alkaloid, reached 80.3 ng/g in mouse brain after oral dosing, showing that even charged isoquinoline alkaloids can cross the BBB; the uncharged query is expected to be at least as permeable.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Noscapine is a lipophilic, uncharged phthalideisoquinoline alkaloid with a tertiary amine and multiple ether groups; structurally related aporphine and isoquinoline alkaloids consistently show brain penetration, and noscapine itself is recognized as a CNS-active antitussive that crosses the BBB. Therefore, meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct noscapine-specific brain concentration or PET record is present in the supplied evidence; extrapolation relies on structurally related isoquinoline/porphine alkaloids.",
    "Most records are qualitative or single-dose tissue distribution studies; quantitative unbound brain exposure and efflux ratios are not consistently reported."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

